import { expect } from "chai";
import { ethers, fhevm } from "hardhat";
import { RockPaperScissors } from "../../types";
import { HardhatEthersSigner } from "@nomicfoundation/hardhat-ethers/signers";

describe("RockPaperScissors", function () {
    let contract: RockPaperScissors;
    let contractAddress: string;
    let signers: { deployer: HardhatEthersSigner; alice: HardhatEthersSigner; bob: HardhatEthersSigner };

    before(async function () {
        const ethSigners = await ethers.getSigners();
        signers = {
            deployer: ethSigners[0],
            alice: ethSigners[1],
            bob: ethSigners[2],
        };
    });

    beforeEach(async function () {
        if (!fhevm.isMock) {
            this.skip();
        }
        const factory = await ethers.getContractFactory("RockPaperScissors");
        contract = (await factory.deploy()) as RockPaperScissors;
        contractAddress = await contract.getAddress();
    });

    it("should allow a full game flow (Alice Rock vs Bob Scissors -> Alice Wins)", async function () {
        // 1. Alice creates game with Rock (1)
        const encMoveAlice = await fhevm.createEncryptedInput(contractAddress, signers.alice.address)
            .add8(1)
            .encrypt();

        await contract.connect(signers.alice).createGame(
            encMoveAlice.handles[0],
            encMoveAlice.inputProof
        );

        // 2. Bob joins with Scissors (3)
        const encMoveBob = await fhevm.createEncryptedInput(contractAddress, signers.bob.address)
            .add8(3)
            .encrypt();

        await contract.connect(signers.bob).joinGame(
            1, // gameId
            encMoveBob.handles[0],
            encMoveBob.inputProof
        );

        // 3. Reveal
        await contract.connect(signers.alice).revealGame(1);

        const game = await contract.games(1);
        expect(game.isFinished).to.be.true;
    });
});

private-age-verification.contract:
// SPDX-License-Identifier: BSD-3-Clause-Clear
pragma solidity ^0.8.24;

import "@fhevm/solidity/lib/FHE.sol";
import "encrypted-types/EncryptedTypes.sol";
import { ZamaEthereumConfig } from "@fhevm/solidity/config/ZamaConfig.sol";

contract PrivateAgeVerification is ZamaEthereumConfig {
    address public owner;

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    // Encrypted storage of user birth years
    mapping(address => euint32) private userBirthYears;
    mapping(address => bool) public isRegistered;

    constructor() {
        owner = msg.sender;
    }

    function registerBirthYear(externalEuint32 _encryptedBirthYear, bytes calldata _inputProof) public {
        userBirthYears[msg.sender] = FHE.fromExternal(_encryptedBirthYear, _inputProof);
        isRegistered[msg.sender] = true;

        FHE.allowThis(userBirthYears[msg.sender]);
        FHE.allow(userBirthYears[msg.sender], msg.sender);
    }

    // Returns an encrypted boolean indicating if the user is older than _minAge
    // We calculate age as: CurrentYear - BirthYear >= MinAge
    // <=> CurrentYear - MinAge >= BirthYear
    function isOverAge(uint256 _currentYear, uint32 _minAge) public returns (ebool) {
        require(isRegistered[msg.sender], "User not registered");

        // ageLimitYear = CurrentYear - MinAge
        // User must be born on or before this year.
        uint32 ageLimitYear = uint32(_currentYear - _minAge);

        // We check: ageLimitYear >= BirthYear
        ebool isOlder = FHE.ge(FHE.asEuint32(ageLimitYear), userBirthYears[msg.sender]);

        return isOlder;
    }

    // Non-view function to generate and share proof
    function proveAgeTo(address _verifier, uint256 _currentYear, uint32 _minAge) public {
        require(isRegistered[msg.sender], "User not registered");

        uint32 ageLimitYear = uint32(_currentYear - _minAge);
        ebool isOlder = FHE.ge(FHE.asEuint32(ageLimitYear), userBirthYears[msg.sender]);

        FHE.allow(isOlder, _verifier);
        FHE.allow(isOlder, msg.sender);
    }
}

