import { FhevmType, HardhatFhevmRuntimeEnvironment } from "@fhevm/hardhat-plugin";
import { HardhatEthersSigner } from "@nomicfoundation/hardhat-ethers/signers";
import { expect } from "chai";
import { ethers } from "hardhat";
import * as hre from "hardhat";

import { FHEIfThenElse, FHEIfThenElse__factory } from "../../../types";
import type { Signers } from "../../types";

async function deployFixture() {
  // Contracts are deployed using the first signer/account by default
  const factory = (await ethers.getContractFactory("FHEIfThenElse")) as FHEIfThenElse__factory;
  const fheIfThenElse = (await factory.deploy()) as FHEIfThenElse;
  const fheIfThenElse_address = await fheIfThenElse.getAddress();

  return { fheIfThenElse, fheIfThenElse_address };
}

/**
 * This trivial example demonstrates the FHE encryption mechanism
 * and highlights a common pitfall developers may encounter.
 */
describe("FHEIfThenElse", function () {
  let contract: FHEIfThenElse;
  let contractAddress: string;
  let signers: Signers;
  let bob: HardhatEthersSigner;

  before(async function () {
    // Check whether the tests are running against an FHEVM mock environment
    if (!hre.fhevm.isMock) {
      throw new Error(`This hardhat test suite cannot run on Sepolia Testnet`);
    }

    const ethSigners: HardhatEthersSigner[] = await ethers.getSigners();
    signers = { owner: ethSigners[0], alice: ethSigners[1] };
    bob = ethSigners[2];
  });

  beforeEach(async function () {
    // Deploy a new contract each time we run a new test
    const deployment = await deployFixture();
    contractAddress = deployment.fheIfThenElse_address;
    contract = deployment.fheIfThenElse;
  });

  it("a >= b ? a : b should succeed", async function () {
    const fhevm: HardhatFhevmRuntimeEnvironment = hre.fhevm;

    let tx;

    // Let's compute `a >= b ? a : b`
    const a = 80;
    const b = 123;

    // Alice encrypts and sets `a` as 80
    const inputA = await fhevm.createEncryptedInput(contractAddress, signers.alice.address).add8(a).encrypt();
    tx = await contract.connect(signers.alice).setA(inputA.handles[0], inputA.inputProof);
    await tx.wait();

    // Alice encrypts and sets `b` as 203
    const inputB = await fhevm.createEncryptedInput(contractAddress, signers.alice.address).add8(b).encrypt();
    tx = await contract.connect(signers.alice).setB(inputB.handles[0], inputB.inputProof);
    await tx.wait();

    // Why Bob has FHE permissions to execute the operation in this case ?
    // See `computeAPlusB()` in `FHEAdd.sol` for a detailed answer
    tx = await contract.connect(bob).computeMax();
    await tx.wait();

    const encryptedMax = await contract.result();

    const clearMax = await fhevm.userDecryptEuint(
      FhevmType.euint8, // Specify the encrypted type
      encryptedMax,
      contractAddress, // The contract address
      bob, // The user wallet
    );

    expect(clearMax).to.equal(a >= b ? a : b);
  });

  it("should succeed when A > B", async function () {
    const fhevm: HardhatFhevmRuntimeEnvironment = hre.fhevm;
    const a = 200;
    const b = 100;

    const inputA = await fhevm.createEncryptedInput(contractAddress, signers.alice.address).add8(a).encrypt();
    await (await contract.connect(signers.alice).setA(inputA.handles[0], inputA.inputProof)).wait();

    const inputB = await fhevm.createEncryptedInput(contractAddress, signers.alice.address).add8(b).encrypt();
    await (await contract.connect(signers.alice).setB(inputB.handles[0], inputB.inputProof)).wait();

    await (await contract.connect(bob).computeMax()).wait();
    const encryptedMax = await contract.result();
    const clearMax = await fhevm.userDecryptEuint(FhevmType.euint8, encryptedMax, contractAddress, bob);
    expect(clearMax).to.equal(200);
  });

  it("should succeed when A == B", async function () {
    const fhevm: HardhatFhevmRuntimeEnvironment = hre.fhevm;
    const val = 50;

    const inputA = await fhevm.createEncryptedInput(contractAddress, signers.alice.address).add8(val).encrypt();
    await (await contract.connect(signers.alice).setA(inputA.handles[0], inputA.inputProof)).wait();

    const inputB = await fhevm.createEncryptedInput(contractAddress, signers.alice.address).add8(val).encrypt();
    await (await contract.connect(signers.alice).setB(inputB.handles[0], inputB.inputProof)).wait();

    await (await contract.connect(bob).computeMax()).wait();
    const encryptedMax = await contract.result();
    const clearMax = await fhevm.userDecryptEuint(FhevmType.euint8, encryptedMax, contractAddress, bob);
    expect(clearMax).to.equal(50);
  });
});

access-control.contract:
// SPDX-License-Identifier: BSD-3-Clause-Clear
pragma solidity ^0.8.24;

import { FHE, euint32, externalEuint32 } from "@fhevm/solidity/lib/FHE.sol";
import { ZamaEthereumConfig } from "@fhevm/solidity/config/ZamaConfig.sol";

/// @title Access Control Example
/// @notice Demonstrates FHE.allow and FHE.allowTransient for controlling access to encrypted data.
contract AccessControlExample is ZamaEthereumConfig {
    euint32 private _secureValue;

    // Event to emit for testing transient allowance
    event ValueAccessed(address indexed by);

    constructor() {
        // Initialize with 0
        _secureValue = FHE.asEuint32(0);
        FHE.allowThis(_secureValue);
    }

    /// @notice Sets a new secure value.
    /// @param input The encrypted value to set.
    /// @param inputProof The proof for the encrypted value.
    function setSecureValue(externalEuint32 input, bytes calldata inputProof) external {
        _secureValue = FHE.fromExternal(input, inputProof);
        FHE.allowThis(_secureValue);
    }

    /// @notice Grants persistent access to the caller.
    function grantAccessToSender() external {
        FHE.allow(_secureValue, msg.sender);
    }

    /// @notice Grants persistent access to a specific user.
    /// @param user The address to grant access to.
    function grantAccess(address user) external {
        FHE.allow(_secureValue, user);
    }

    /// @notice Returns the encrypted secure value.
    /// @return The encrypted euint32 handle.
    function getSecureValue() external view returns (euint32) {
        return _secureValue;
    }

    /// @notice Demonstrates transient allowance.
    /// @dev Allows a specific address (e.g. another contract) to access the value temporarily.
    /// @param other The address to grant transient access to.
    function temporaryUse(address other) external {
        FHE.allowTransient(_secureValue, other);
        emit ValueAccessed(other);
    }
}

