import { HardhatEthersSigner } from "@nomicfoundation/hardhat-ethers/signers";
import { ethers, fhevm } from "hardhat";
import { SwapERC7984ERC7984, MockConfidentialToken } from "../../types";
import { expect } from "chai";
import { FhevmType } from "@fhevm/hardhat-plugin";

describe("SwapERC7984ERC7984", function () {
  let signers: { deployer: HardhatEthersSigner; alice: HardhatEthersSigner; bob: HardhatEthersSigner };
  let swapContract: SwapERC7984ERC7984;
  let tokenA: MockConfidentialToken;
  let tokenB: MockConfidentialToken;
  let swapAddress: string;
  let tokenAAddress: string;
  let tokenBAddress: string;

  before(async function () {
    const ethSigners = await ethers.getSigners();
    signers = { deployer: ethSigners[0], alice: ethSigners[1], bob: ethSigners[2] };
  });

  beforeEach(async function () {
    // Deploy Tokens
    const confFactory = await ethers.getContractFactory("MockConfidentialToken");

    tokenA = (await confFactory.deploy()) as MockConfidentialToken;
    tokenAAddress = await tokenA.getAddress();

    tokenB = (await confFactory.deploy()) as MockConfidentialToken;
    tokenBAddress = await tokenB.getAddress();

    // Deploy Swap
    const swapFactory = await ethers.getContractFactory("SwapERC7984ERC7984");
    swapContract = (await swapFactory.deploy(tokenAAddress, tokenBAddress)) as SwapERC7984ERC7984;
    swapAddress = await swapContract.getAddress();
  });

  /**
   * @chapter openzeppelin
   * @example erc7984-erc7984-swap
   * @summary Private atomic swap between two confidential ERC7984 tokens.
   */
  it("should swap confidential tokens when amounts match", async function () {
    const amountA = 100;
    const amountB = 200;

    // Alice has Token A
    await tokenA.mint(signers.alice.address, amountA);
    await tokenA.connect(signers.alice).setOperator(swapAddress, "281474976710655");

    // Bob has Token B
    await tokenB.mint(signers.bob.address, amountB);
    await tokenB.connect(signers.bob).setOperator(swapAddress, "281474976710655");

    // Alice creates order: Offer 100 A, Ask 200 B
    const inputA = await fhevm.createEncryptedInput(swapAddress, signers.alice.address)
      .add64(amountA)
      .encrypt();

    const inputAskB = await fhevm.createEncryptedInput(swapAddress, signers.alice.address)
      .add64(amountB)
      .encrypt();

    await swapContract.connect(signers.alice).createOrder(
      inputA.handles[0], inputA.inputProof,
      inputAskB.handles[0], inputAskB.inputProof
    );

    // Alice's balance A should be 0
    const aliceBalanceHandleA = await tokenA.confidentialBalanceOf(signers.alice.address);
    const aliceBalanceA = await fhevm.userDecryptEuint(FhevmType.euint64, aliceBalanceHandleA, tokenAAddress, signers.alice);
    expect(aliceBalanceA).to.equal(0);

    // Bob fills order: Sends 200 B
    const inputB = await fhevm.createEncryptedInput(swapAddress, signers.bob.address)
      .add64(amountB)
      .encrypt();

    await swapContract.connect(signers.bob).fillOrder(0, inputB.handles[0], inputB.inputProof);

    // Check Final Balances

    // Alice should have 200 Token B
    const aliceBalanceHandleB = await tokenB.confidentialBalanceOf(signers.alice.address);
    const aliceBalanceB = await fhevm.userDecryptEuint(FhevmType.euint64, aliceBalanceHandleB, tokenBAddress, signers.alice);
    expect(aliceBalanceB).to.equal(amountB);

    // Bob should have 100 Token A
    const bobBalanceHandleA = await tokenA.confidentialBalanceOf(signers.bob.address);
    const bobBalanceA = await fhevm.userDecryptEuint(FhevmType.euint64, bobBalanceHandleA, tokenAAddress, signers.bob);
    expect(bobBalanceA).to.equal(amountA);
  });

  it("should fail when amounts do not match", async function () {
    const amountA = 100;
    const askAmountB = 200;
    const wrongAmountB = 150;

    // Alice Setup
    await tokenA.mint(signers.alice.address, amountA);
    await tokenA.connect(signers.alice).setOperator(swapAddress, "281474976710655");

    const inputA = await fhevm.createEncryptedInput(swapAddress, signers.alice.address)
      .add64(amountA)
      .encrypt();
    const inputAskB = await fhevm.createEncryptedInput(swapAddress, signers.alice.address)
      .add64(askAmountB)
      .encrypt();

    await swapContract.connect(signers.alice).createOrder(
      inputA.handles[0], inputA.inputProof,
      inputAskB.handles[0], inputAskB.inputProof
    );

    // Bob Setup
    await tokenB.mint(signers.bob.address, wrongAmountB);
    await tokenB.connect(signers.bob).setOperator(swapAddress, "281474976710655");

    // Bob tries to fill with wrong amount
    const inputB = await fhevm.createEncryptedInput(swapAddress, signers.bob.address)
      .add64(wrongAmountB)
      .encrypt();

    // Should not revert, but swap effectively 0
    await swapContract.connect(signers.bob).fillOrder(0, inputB.handles[0], inputB.inputProof);

    // Check that balances did NOT change (Alice still has 0 A effective? No, A is locked in contract)
    // Alice balance A (in contract loop) -> should return to her? 
    // Wait, if swap fails (0 transfer), Alice's A is still in contract.
    // Example logic assumes usage of select closes order. 
    // Bob should have kept his Token B (transferred 0).

    // Check Bob Balance B: should be full 'wrongAmountB'
    const bobBalanceHandleB = await tokenB.confidentialBalanceOf(signers.bob.address);
    const bobBalanceB = await fhevm.userDecryptEuint(FhevmType.euint64, bobBalanceHandleB, tokenBAddress, signers.bob);
    expect(bobBalanceB).to.equal(wrongAmountB);
  });
});

vesting-wallet.contract:
// SPDX-License-Identifier: BSD-3-Clause-Clear
pragma solidity ^0.8.24;

import { ERC7984 } from "@openzeppelin/confidential-contracts/token/ERC7984/ERC7984.sol";
import { IERC7984 } from "@openzeppelin/confidential-contracts/interfaces/IERC7984.sol";
import { ZamaEthereumConfig } from "@fhevm/solidity/config/ZamaConfig.sol";
import { FHE, euint64, externalEuint64 } from "@fhevm/solidity/lib/FHE.sol";

/// @title Confidential Vesting Wallet
/// @notice Handles the vesting of ERC7984 confidential tokens for a beneficiary.
contract VestingWalletExample is ZamaEthereumConfig {
    IERC7984 public immutable token;
    address public immutable beneficiary;
    uint64 public immutable start;
    uint64 public immutable duration;

    euint64 private _totalReleased;
    euint64 private _totalAllocation;
    bool private _initialized;

    event TokensReleased(address indexed beneficiary, uint256 amount); // Amount is hidden, so maybe don't emit amount? Or emit encrypted handle? 
    // Standard Events usually emit amount, but here it's confidential. We just emit "Something happened".

    constructor(
        address _token,
        address _beneficiary,
        uint64 _startTimestamp,
        uint64 _durationSeconds
    ) {
        token = IERC7984(_token);
        beneficiary = _beneficiary;
        start = _startTimestamp;
        duration = _durationSeconds;
        _totalReleased = FHE.asEuint64(0);
        FHE.allowThis(_totalReleased);
    }

    /// @notice Initialize the vesting by depositing tokens (can be done once)
    function initialize(externalEuint64 encryptedAmount, bytes calldata proof) external {
        require(!_initialized, "Already initialized");
        euint64 amount = FHE.fromExternal(encryptedAmount, proof);

        FHE.allow(amount, address(token));
        token.confidentialTransferFrom(msg.sender, address(this), amount);

        _totalAllocation = amount;
        FHE.allowThis(_totalAllocation);

        _initialized = true;
    }

    /// @notice Release vested tokens to beneficiary
    function release() external {
        uint64 currentTimestamp = uint64(block.timestamp);
        require(currentTimestamp > start, "Vesting has not started");

        euint64 vested = _vestedAmount(currentTimestamp);
        euint64 releasable = FHE.sub(vested, _totalReleased);

        // Update released state
        _totalReleased = FHE.add(_totalReleased, releasable);
        FHE.allowThis(_totalReleased); // Allow contract to use updated value

        // Transfer releasable amount to beneficiary
        FHE.allow(releasable, address(token));
        token.confidentialTransfer(beneficiary, releasable);
    }

    /// @notice Calculates the amount that has already vested
    function _vestedAmount(uint64 timestamp) internal returns (euint64) {
        if (timestamp < start) {
            return FHE.asEuint64(0);
        } else if (timestamp >= start + duration) {
            return _totalAllocation;
        } else {
            // Linear vesting: allocation * (time - start) / duration
            uint64 timePassed = timestamp - start;
            // euint64 * uint64 (scalar) -> euint64
            euint64 vested = FHE.mul(_totalAllocation, FHE.asEuint64(timePassed));
            // euint64 / uint64 (scalar) -> euint64
            // Zama FHEVM supports scalar operations.
            return FHE.div(vested, duration);
        }
    }

    // View function to check vested amount (only beneficiary should be able to see?)
    // Actually, we can return a handle for the beneficiary.
    function vestedAmount() external view returns (euint64) {
         // In a real app, we'd need to re-encrypt this for the caller (beneficiary) using FHE.seal() 
         // or just return the handle if they have permission?
         // Since allowThis is used, we need to allow beneficiary to view it.
         // But view functions cannot change state (FHE.allow).
         // So we can't easily "view" the exact result unless we use FHE.allowTransient in a tx.
         // For this example, we skip the view function or return 0.
         // Best practice: The beneficiary calls a TX to "check and re-encrypt" if they want to see status.
         return _totalReleased; // This is a handle, only readable if allowed.
    }
}

// Helpers
contract MockConfidentialToken is ERC7984, ZamaEthereumConfig {
    constructor() ERC7984("Mock Private", "PRIV", "") {}
    function mint(address to, uint64 amount) public { _mint(to, FHE.asEuint64(amount)); }
}

vesting-wallet.test:
import { HardhatEthersSigner } from "@nomicfoundation/hardhat-ethers/signers";
import { ethers, fhevm } from "hardhat";
import { VestingWalletExample, MockConfidentialToken } from "../../types";
import { expect } from "chai";
import { FhevmType } from "@fhevm/hardhat-plugin";
import { time } from "@nomicfoundation/hardhat-network-helpers";

describe("VestingWalletExample", function () {
  let signers: { deployer: HardhatEthersSigner; beneficiary: HardhatEthersSigner };
  let vesting: VestingWalletExample;
  let token: MockConfidentialToken;
  let vestingAddress: string;
  let tokenAddress: string;
  let startTimestamp: number;
  const DURATION = 1000;
  const ALLOCATION = 1000;

  before(async function () {
    const ethSigners = await ethers.getSigners();
    signers = { deployer: ethSigners[0], beneficiary: ethSigners[1] };
  });

  beforeEach(async function () {
    // Deploy Token
    const tokenFactory = await ethers.getContractFactory("MockConfidentialToken");
    token = (await tokenFactory.deploy()) as MockConfidentialToken;
    tokenAddress = await token.getAddress();

    // Setup Start Time
    startTimestamp = (await time.latest()) + 100;

    // Deploy Vesting Wallet
    const vestingFactory = await ethers.getContractFactory("VestingWalletExample");
    vesting = (await vestingFactory.deploy(
      tokenAddress,
      signers.beneficiary.address,
      startTimestamp,
      DURATION
    )) as VestingWalletExample;
    vestingAddress = await vesting.getAddress();

    // Mint and Initialize
    await token.mint(signers.deployer.address, ALLOCATION);
    await token.connect(signers.deployer).setOperator(vestingAddress, "281474976710655");

    const input = await fhevm.createEncryptedInput(vestingAddress, signers.deployer.address)
      .add64(ALLOCATION)
      .encrypt();

    await vesting.initialize(input.handles[0], input.inputProof);
  });

  /**
   * @chapter openzeppelin
   * @example vesting-wallet
   * @summary Demonstrates confidential linear vesting.
   */
  it("should release tokens over time", async function () {
    // 1. Check initial release (should be 0)
    await time.increaseTo(startTimestamp - 10);
    // Try to release
    await expect(vesting.release()).to.be.revertedWith("Vesting has not started");

    // 2. Advance to 50% duration
    await time.increaseTo(startTimestamp + DURATION / 2);

    // Release
    await vesting.release();

    // Check Beneficiary Balance (should be ~500)
    const balanceHandle = await token.confidentialBalanceOf(signers.beneficiary.address);
    const balance = await fhevm.userDecryptEuint(
      FhevmType.euint64,
      balanceHandle,
      tokenAddress,
      signers.beneficiary
    );

    // Allow small margin of error for time precision
    expect(balance).to.be.closeTo(500, 5);

    // 3. Advance to end
    await time.increaseTo(startTimestamp + DURATION + 1);

    // Release remaining
    await vesting.release();

    // Check Beneficiary Balance (should be 1000)
    const finalBalanceHandle = await token.confidentialBalanceOf(signers.beneficiary.address);
    const finalBalance = await fhevm.userDecryptEuint(
      FhevmType.euint64,
      finalBalanceHandle,
      tokenAddress,
      signers.beneficiary
    );
    expect(finalBalance).to.equal(ALLOCATION);
  });
});
